def tools(s):
 s=s.replace('import com.forestry.counter.R','''import com.forestry.counter.R
import com.forestry.counter.presentation.components.maps.rememberMapModalStatusBarPolicy
import com.forestry.counter.presentation.components.maps.MapModalStatusBarEffect''',1)
 start=s.index('internal fun MapWorkspaceTools(')
 tail=s[start:]
 tail=tail.replace('''    val density = LocalDensity.current.density
    fun open''','''    val density = LocalDensity.current.density
    val statusBars = rememberMapModalStatusBarPolicy()
    fun open''',1)
 needle='''        containerColor = MaterialTheme.colorScheme.surface,
    ) {
        Column('''
 replacement='''        containerColor = MaterialTheme.colorScheme.surface,
    ) {
        MapModalStatusBarEffect(statusBars)
        Column('''
 assert needle in tail;tail=tail.replace(needle,replacement,1)
 return s[:start]+tail

